method get_positive(l: seq<int>) returns (result: seq<int>)
    requires |l| > 0 // List must not be empty
    ensures forall i :: 0 <= i < |result| ==> result[i] > 0 // All elements in the result are positive
    ensures |result| <= |l| // Result can have at most the same number of elements as the input list
{
    var temp := new seq<int>();
    var i := 0;
    while i < |l|
        invariant 0 <= i <= |l| // i is within the bounds of the input list
        invariant |temp| <= |l| // temp has at most the same number of elements as l
    {
        if l[i] > 0 {
            temp := temp + [l[i]]; // Add positive element to temp
        }
        i := i + 1;
    }
    result := temp; // Return the filtered list of positive numbers
}
```

